INSERT INTO cursos (id, titulo, descricao, carga_horaria_minutos, id_categoria, id_area, nivel, tema, instrutor_nome, instrutor_cargo, nota, total_avaliacoes, destaque, lancamento, destaque_do_mes) VALUES
  (1, 'Comunicação Assertiva no Trabalho', 'Comunique-se com clareza, empatia e objetividade com colegas, gestores e clientes.', 120, 'comunicacao', 'lideranca', 'intermediario', 'azul', 'Carla Lima', 'Especialista em Comunicação Corporativa', 4.9, 320, TRUE, FALSE, FALSE),
  (2, 'Gestão do Tempo e Prioridades', 'Técnicas práticas para priorizar, reduzir interrupções e manter rotinas de alta entrega.', 90, 'produtividade', 'operacoes', 'iniciante', 'ambar', 'Marcos Silva', 'Consultor de Produtividade', 4.8, 412, FALSE, TRUE, FALSE),
  (3, 'Resolução de Problemas e Tomada de Decisão', 'Estruture hipóteses, analise cenários e decida com base em evidências.', 120, 'lideranca', 'lideranca', 'avancado', 'roxo', 'Renata Neves', 'Doutora em Gestão', 4.9, 189, TRUE, FALSE, FALSE),
  (4, 'Excel para o Dia a Dia', 'O essencial de planilhas para organizar dados, montar relatórios e automatizar tarefas.', 180, 'dados', 'financas', 'iniciante', 'ciano', 'Felipe Alves', 'Analista de BI', 4.7, 540, FALSE, FALSE, FALSE),
  (5, 'Liderança Situacional e Feedback', 'Adapte seu estilo de liderança, conduza 1:1 e dê feedbacks que geram mudança.', 240, 'lideranca', 'rh', 'intermediario', 'teal', 'Beatriz Albuquerque', 'Coordenadora de RH', 5.0, 186, TRUE, FALSE, FALSE),
  (6, 'Inteligência Emocional no Trabalho', 'Autoconhecimento, autorregulação sob pressão e resiliência no dia a dia.', 120, 'desenvolvimento-humano', 'rh', 'todos', 'rosa', 'Paula Moreira', 'Psicóloga Organizacional', 4.8, 152, FALSE, TRUE, FALSE),
  (7, 'Excel Avançado e Dashboards', 'Tabelas dinâmicas, PROCX, Power Query e dashboards gerenciais.', 300, 'dados', 'financas', 'avancado', 'grafite', 'Felipe Alves', 'Analista de BI', 4.9, 310, FALSE, FALSE, FALSE),
  (8, 'Gestão de Conflitos', 'Transforme divergências em colaboração com técnicas estruturadas de mediação.', 150, 'desenvolvimento-humano', 'vendas', 'intermediario', 'laranja', 'Paula Moreira', 'Psicóloga Organizacional', 4.6, 77, FALSE, FALSE, FALSE),
  (9, 'Apresentações de Alto Impacto', 'Storytelling, slides limpos e oratória para reuniões decisivas.', 180, 'comunicacao', 'marketing', 'intermediario', 'azul', 'Carla Lima', 'Especialista em Comunicação Corporativa', 4.9, 244, FALSE, FALSE, FALSE),
  (10, 'Fundamentos da Cultura Oscorp', 'Valores, ferramentas internas e rotinas para começar com o pé direito.', 60, 'conformidade', 'rh', 'iniciante', 'verde', 'Beatriz Albuquerque', 'Coordenadora de RH', 4.7, 890, FALSE, FALSE, FALSE),
  (11, 'Segurança da Informação e LGPD', 'Proteja dados, reconheça engenharia social e cumpra a legislação.', 120, 'conformidade', 'tecnologia', 'todos', 'grafite', 'Rafael Costa', 'Especialista em Segurança', 4.9, 615, TRUE, FALSE, FALSE),
  (12, 'IA Generativa para Produtividade', 'Use ferramentas de IA para automatizar relatórios, análises e rotinas.', 360, 'tecnologia', 'tecnologia', 'intermediario', 'roxo', 'Roberto Guimarães', 'Pesquisador em IA', 5.0, 98, TRUE, TRUE, TRUE),
  (13, 'Metodologias Ágeis: Scrum e Kanban', 'Rituais ágeis, gestão de gargalos e fluxo contínuo em equipes dinâmicas.', 180, 'produtividade', 'operacoes', 'intermediario', 'teal', 'Marcos Silva', 'Consultor de Produtividade', 4.8, 201, FALSE, FALSE, FALSE),
  (14, 'Negociação e Influência', 'Estratégias de alinhamento entre áreas, concessões e construção de consenso.', 190, 'comunicacao', 'vendas', 'avancado', 'laranja', 'Carla Lima', 'Especialista em Comunicação Corporativa', 4.7, 133, FALSE, FALSE, FALSE),
  (15, 'Pesquisa com Usuários', 'Entrevistas, testes de usabilidade e síntese de descobertas para produto.', 150, 'tecnologia', 'design', 'intermediario', 'rosa', 'Camila Rocha', 'Designer UI/UX', 4.8, 64, FALSE, TRUE, FALSE),
  (16, 'Posicionamento de Marca', 'Proposta de valor, mensagens-chave e consistência em todos os canais.', 140, 'comunicacao', 'marketing', 'intermediario', 'ambar', 'Lucas Prado', 'Head de Marketing', 4.6, 58, FALSE, FALSE, FALSE);
