-- =====================================================================
-- Cara Cursos — esquema da base de dados (MySQL 8.0.19+)
--
-- Executar:  mysql -u root -p -e "source backend/sql/cara_cursos.sql"
-- O script é reexecutável: apaga e recria as tabelas e os dados de teste.
--
-- Convenções:
--   * Datas em UTC (a aplicação conecta com connectionTimeZone=UTC).
--   * Durações em minutos (cursos) e segundos (aulas).
--   * Enums em minúsculas, iguais aos valores que a API devolve.
-- =====================================================================

CREATE DATABASE IF NOT EXISTS cara_cursos
  DEFAULT CHARACTER SET utf8mb4
  DEFAULT COLLATE utf8mb4_0900_ai_ci;  -- ai_ci: buscas ignoram acentos e maiúsculas

USE cara_cursos;

-- Usuário dedicado à aplicação (opcional; recomendado em vez de root):
-- CREATE USER IF NOT EXISTS 'caracursos'@'localhost' IDENTIFIED BY 'troque-esta-senha';
-- GRANT SELECT, INSERT, UPDATE, DELETE ON cara_cursos.* TO 'caracursos'@'localhost';

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS notificacoes, certificados, entregas, atividades, materiais,
  progresso_aulas, aulas, matriculas, nivel_cursos, niveis, trilha_cursos, trilhas,
  cursos, areas, categorias, sessoes, usuarios, cargos, departamentos, empresa;
SET FOREIGN_KEY_CHECKS = 1;

-- ---------------------------------------------------------------------
-- Empresa cliente (instalação de uma única empresa)
-- ---------------------------------------------------------------------
CREATE TABLE empresa (
  id                   INT UNSIGNED      NOT NULL,
  nome_fantasia        VARCHAR(120)      NOT NULL,
  razao_social         VARCHAR(160)      NOT NULL,
  cnpj                 CHAR(18)          NOT NULL,
  licencas_contratadas SMALLINT UNSIGNED NOT NULL,
  CONSTRAINT pk_empresa PRIMARY KEY (id)
) ENGINE = InnoDB;

CREATE TABLE departamentos (
  nome VARCHAR(80) NOT NULL,
  CONSTRAINT pk_departamentos PRIMARY KEY (nome)
) ENGINE = InnoDB;

CREATE TABLE cargos (
  nome VARCHAR(80) NOT NULL,
  CONSTRAINT pk_cargos PRIMARY KEY (nome)
) ENGINE = InnoDB;

-- ---------------------------------------------------------------------
-- usuarios
-- senha: HASH (nunca texto puro), formato pbkdf2_sha256$<iterações>$<salt>$<hash>.
--        NULL enquanto o convite não foi aceito (status 'pendente').
-- tipo_perfil: os mesmos papéis do frontend (AuthContext).
-- ---------------------------------------------------------------------
CREATE TABLE usuarios (
  id                   INT UNSIGNED      NOT NULL AUTO_INCREMENT,
  matricula            VARCHAR(12)       NULL,
  nome                 VARCHAR(120)      NOT NULL,
  email                VARCHAR(160)      NOT NULL,
  senha                VARCHAR(255)      NULL,
  tipo_perfil          ENUM('admin', 'rh', 'lider', 'financeiro', 'colaborador')
                       NOT NULL DEFAULT 'colaborador',
  cargo                VARCHAR(80)       NOT NULL,
  departamento         VARCHAR(80)       NOT NULL,
  nivel                TINYINT UNSIGNED  NOT NULL DEFAULT 1,
  status               ENUM('ativo', 'pendente', 'inativo') NOT NULL DEFAULT 'pendente',
  meta_semanal_minutos SMALLINT UNSIGNED NOT NULL DEFAULT 480,
  notificacoes_email   BOOLEAN           NOT NULL DEFAULT TRUE,
  resumo_semanal       BOOLEAN           NOT NULL DEFAULT TRUE,
  ultimo_acesso        DATETIME          NULL,
  criado_em            DATETIME          NOT NULL DEFAULT (UTC_TIMESTAMP()),
  CONSTRAINT pk_usuarios PRIMARY KEY (id),
  CONSTRAINT uk_usuarios_email UNIQUE (email),
  CONSTRAINT uk_usuarios_matricula UNIQUE (matricula),
  CONSTRAINT ck_usuarios_nivel CHECK (nivel BETWEEN 1 AND 4)
) ENGINE = InnoDB;

-- Sessões de login. Guarda só o SHA-256 do token; o token em si fica no cliente.
-- As linhas não são apagadas no logout (revogada_em) para alimentar o painel.
CREATE TABLE sessoes (
  token_hash  CHAR(64)     NOT NULL,
  id_usuario  INT UNSIGNED NOT NULL,
  criada_em   DATETIME     NOT NULL,
  expira_em   DATETIME     NOT NULL,
  revogada_em DATETIME     NULL,
  CONSTRAINT pk_sessoes PRIMARY KEY (token_hash),
  CONSTRAINT fk_sessoes_usuario FOREIGN KEY (id_usuario) REFERENCES usuarios (id) ON DELETE CASCADE,
  INDEX ix_sessoes_criada_em (criada_em)
) ENGINE = InnoDB;

-- ---------------------------------------------------------------------
-- Catálogo
-- ---------------------------------------------------------------------
CREATE TABLE categorias (
  id   VARCHAR(40) NOT NULL,
  nome VARCHAR(80) NOT NULL,
  CONSTRAINT pk_categorias PRIMARY KEY (id)
) ENGINE = InnoDB;

CREATE TABLE areas (
  id           VARCHAR(40) NOT NULL,
  nome         VARCHAR(80) NOT NULL,
  icone        VARCHAR(20) NOT NULL,
  competencias JSON        NOT NULL,
  CONSTRAINT pk_areas PRIMARY KEY (id)
) ENGINE = InnoDB;

-- carga_horaria_minutos: carga horária declarada do curso (a API devolve duracaoMinutos).
CREATE TABLE cursos (
  id                    INT UNSIGNED      NOT NULL AUTO_INCREMENT,
  titulo                VARCHAR(150)      NOT NULL,
  descricao             TEXT              NULL,
  carga_horaria_minutos SMALLINT UNSIGNED NOT NULL,
  id_categoria          VARCHAR(40)       NOT NULL,
  id_area               VARCHAR(40)       NOT NULL,
  nivel                 ENUM('iniciante', 'intermediario', 'avancado', 'todos') NOT NULL,
  tema                  ENUM('azul', 'ambar', 'ciano', 'roxo', 'teal', 'verde', 'rosa', 'grafite', 'laranja')
                        NOT NULL DEFAULT 'azul',
  imagem_url            VARCHAR(500)      NULL,
  instrutor_nome        VARCHAR(120)      NOT NULL,
  instrutor_cargo       VARCHAR(120)      NOT NULL,
  nota                  DECIMAL(2, 1)     NOT NULL DEFAULT 0,
  total_avaliacoes      INT UNSIGNED      NOT NULL DEFAULT 0,
  destaque              BOOLEAN           NOT NULL DEFAULT FALSE,
  lancamento            BOOLEAN           NOT NULL DEFAULT FALSE,
  destaque_do_mes       BOOLEAN           NOT NULL DEFAULT FALSE,
  CONSTRAINT pk_cursos PRIMARY KEY (id),
  CONSTRAINT fk_cursos_categoria FOREIGN KEY (id_categoria) REFERENCES categorias (id),
  CONSTRAINT fk_cursos_area FOREIGN KEY (id_area) REFERENCES areas (id),
  CONSTRAINT ck_cursos_carga_horaria CHECK (carga_horaria_minutos > 0),
  CONSTRAINT ck_cursos_nota CHECK (nota BETWEEN 0 AND 5)
) ENGINE = InnoDB;

CREATE TABLE aulas (
  id               INT UNSIGNED      NOT NULL AUTO_INCREMENT,
  id_curso         INT UNSIGNED      NOT NULL,
  ordem            SMALLINT UNSIGNED NOT NULL,
  titulo           VARCHAR(150)      NOT NULL,
  tipo             ENUM('video', 'avaliacao') NOT NULL DEFAULT 'video',
  duracao_segundos INT UNSIGNED      NOT NULL,
  video_url        VARCHAR(500)      NOT NULL,
  poster_url       VARCHAR(500)      NULL,
  legenda_url      VARCHAR(500)      NULL,
  CONSTRAINT pk_aulas PRIMARY KEY (id),
  CONSTRAINT uk_aulas_curso_ordem UNIQUE (id_curso, ordem),
  CONSTRAINT fk_aulas_curso FOREIGN KEY (id_curso) REFERENCES cursos (id) ON DELETE CASCADE
) ENGINE = InnoDB;

CREATE TABLE materiais (
  id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_curso      INT UNSIGNED NOT NULL,
  nome          VARCHAR(200) NOT NULL,
  tamanho_bytes INT UNSIGNED NOT NULL,
  url           VARCHAR(500) NULL,
  CONSTRAINT pk_materiais PRIMARY KEY (id),
  CONSTRAINT fk_materiais_curso FOREIGN KEY (id_curso) REFERENCES cursos (id) ON DELETE CASCADE
) ENGINE = InnoDB;

CREATE TABLE atividades (
  id        INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_curso  INT UNSIGNED NOT NULL,
  titulo    VARCHAR(150) NOT NULL,
  descricao TEXT         NOT NULL,
  prazo     DATETIME     NOT NULL,
  CONSTRAINT pk_atividades PRIMARY KEY (id),
  CONSTRAINT fk_atividades_curso FOREIGN KEY (id_curso) REFERENCES cursos (id) ON DELETE CASCADE
) ENGINE = InnoDB;

-- ---------------------------------------------------------------------
-- Trilhas e níveis (sequências de cursos)
-- ---------------------------------------------------------------------
CREATE TABLE trilhas (
  id           INT UNSIGNED NOT NULL AUTO_INCREMENT,
  titulo       VARCHAR(150) NOT NULL,
  descricao    TEXT         NOT NULL,
  nivel        ENUM('iniciante', 'intermediario', 'avancado', 'todos') NOT NULL,
  tema         VARCHAR(20)  NOT NULL,
  competencias JSON         NOT NULL,
  CONSTRAINT pk_trilhas PRIMARY KEY (id)
) ENGINE = InnoDB;

CREATE TABLE trilha_cursos (
  id_trilha INT UNSIGNED      NOT NULL,
  id_curso  INT UNSIGNED      NOT NULL,
  ordem     SMALLINT UNSIGNED NOT NULL,
  CONSTRAINT pk_trilha_cursos PRIMARY KEY (id_trilha, id_curso),
  CONSTRAINT fk_trilha_cursos_trilha FOREIGN KEY (id_trilha) REFERENCES trilhas (id) ON DELETE CASCADE,
  CONSTRAINT fk_trilha_cursos_curso FOREIGN KEY (id_curso) REFERENCES cursos (id) ON DELETE CASCADE
) ENGINE = InnoDB;

CREATE TABLE niveis (
  id           INT UNSIGNED     NOT NULL AUTO_INCREMENT,
  ordem        TINYINT UNSIGNED NOT NULL,
  titulo       VARCHAR(150)     NOT NULL,
  perfil       VARCHAR(80)      NOT NULL,
  competencias JSON             NOT NULL,
  CONSTRAINT pk_niveis PRIMARY KEY (id),
  CONSTRAINT uk_niveis_ordem UNIQUE (ordem)
) ENGINE = InnoDB;

CREATE TABLE nivel_cursos (
  id_nivel INT UNSIGNED      NOT NULL,
  id_curso INT UNSIGNED      NOT NULL,
  ordem    SMALLINT UNSIGNED NOT NULL,
  CONSTRAINT pk_nivel_cursos PRIMARY KEY (id_nivel, id_curso),
  CONSTRAINT fk_nivel_cursos_nivel FOREIGN KEY (id_nivel) REFERENCES niveis (id) ON DELETE CASCADE,
  CONSTRAINT fk_nivel_cursos_curso FOREIGN KEY (id_curso) REFERENCES cursos (id) ON DELETE CASCADE
) ENGINE = InnoDB;

-- ---------------------------------------------------------------------
-- Aprendizagem do aluno
-- ---------------------------------------------------------------------

-- progresso: porcentagem de aulas concluídas (0 a 100), recalculada a cada aula concluída.
-- Um usuário só pode estar matriculado uma vez em cada curso.
CREATE TABLE matriculas (
  id             INT UNSIGNED     NOT NULL AUTO_INCREMENT,
  id_usuario     INT UNSIGNED     NOT NULL,
  id_curso       INT UNSIGNED     NOT NULL,
  progresso      TINYINT UNSIGNED NOT NULL DEFAULT 0,
  data_matricula DATETIME         NOT NULL DEFAULT (UTC_TIMESTAMP()),
  data_conclusao DATETIME         NULL,
  CONSTRAINT pk_matriculas PRIMARY KEY (id),
  CONSTRAINT uk_matriculas_usuario_curso UNIQUE (id_usuario, id_curso),
  CONSTRAINT ck_matriculas_progresso CHECK (progresso BETWEEN 0 AND 100),
  CONSTRAINT fk_matriculas_usuario FOREIGN KEY (id_usuario) REFERENCES usuarios (id) ON DELETE CASCADE,
  CONSTRAINT fk_matriculas_curso FOREIGN KEY (id_curso) REFERENCES cursos (id) ON DELETE RESTRICT
) ENGINE = InnoDB;

-- Sem linha = aula pendente.
CREATE TABLE progresso_aulas (
  id_usuario       INT UNSIGNED NOT NULL,
  id_aula          INT UNSIGNED NOT NULL,
  posicao_segundos INT UNSIGNED NOT NULL DEFAULT 0,
  status           ENUM('em_andamento', 'concluida') NOT NULL DEFAULT 'em_andamento',
  atualizado_em    DATETIME     NOT NULL,
  concluida_em     DATETIME     NULL,
  CONSTRAINT pk_progresso_aulas PRIMARY KEY (id_usuario, id_aula),
  CONSTRAINT fk_progresso_aulas_usuario FOREIGN KEY (id_usuario) REFERENCES usuarios (id) ON DELETE CASCADE,
  CONSTRAINT fk_progresso_aulas_aula FOREIGN KEY (id_aula) REFERENCES aulas (id) ON DELETE CASCADE,
  INDEX ix_progresso_aulas_atualizado (id_usuario, atualizado_em)
) ENGINE = InnoDB;

CREATE TABLE entregas (
  id_atividade INT UNSIGNED NOT NULL,
  id_usuario   INT UNSIGNED NOT NULL,
  resposta     TEXT         NOT NULL,
  entregue_em  DATETIME     NOT NULL,
  CONSTRAINT pk_entregas PRIMARY KEY (id_atividade, id_usuario),
  CONSTRAINT fk_entregas_atividade FOREIGN KEY (id_atividade) REFERENCES atividades (id) ON DELETE CASCADE,
  CONSTRAINT fk_entregas_usuario FOREIGN KEY (id_usuario) REFERENCES usuarios (id) ON DELETE CASCADE
) ENGINE = InnoDB;

-- Emitido ao concluir um curso (tipo 'curso') ou todos os cursos de um nível (tipo 'nivel').
CREATE TABLE certificados (
  id            INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_usuario    INT UNSIGNED NOT NULL,
  tipo          ENUM('curso', 'nivel') NOT NULL,
  id_referencia INT UNSIGNED NOT NULL,
  titulo        VARCHAR(150) NOT NULL,
  origem        VARCHAR(40)  NOT NULL,
  codigo        VARCHAR(20)  NOT NULL,
  emitido_em    DATETIME     NOT NULL,
  CONSTRAINT pk_certificados PRIMARY KEY (id),
  CONSTRAINT uk_certificados_codigo UNIQUE (codigo),
  CONSTRAINT uk_certificados_referencia UNIQUE (id_usuario, tipo, id_referencia),
  CONSTRAINT fk_certificados_usuario FOREIGN KEY (id_usuario) REFERENCES usuarios (id) ON DELETE CASCADE
) ENGINE = InnoDB;

CREATE TABLE notificacoes (
  id         INT UNSIGNED NOT NULL AUTO_INCREMENT,
  id_usuario INT UNSIGNED NOT NULL,
  titulo     VARCHAR(150) NOT NULL,
  descricao  VARCHAR(300) NOT NULL,
  link       VARCHAR(200) NULL,
  lida       BOOLEAN      NOT NULL DEFAULT FALSE,
  criada_em  DATETIME     NOT NULL,
  CONSTRAINT pk_notificacoes PRIMARY KEY (id),
  CONSTRAINT fk_notificacoes_usuario FOREIGN KEY (id_usuario) REFERENCES usuarios (id) ON DELETE CASCADE,
  INDEX ix_notificacoes_usuario (id_usuario, criada_em)
) ENGINE = InnoDB;

